mem = dict()

def C(f,h,kf,kh,kf_init,kh_init):
    if f + h == 0:
        return 1
    else:
        if (f,h,kf,kh) not in mem:
            mem[(f,h,kf,kh)] = F(f,h,kf,kh,kf_init,kh_init) + H(f,h,kf,kh,kf_init,kh_init)
        return mem[(f,h,kf,kh)]

def F(f,h,kf,kh,kf_init,kh_init):
    if f>0 and kf>0:
        return C(f-1,h,kf-1,kh_init,kf_init,kh_init)
    else:
        return 0

def H(f,h,kf,kh,kf_init,kh_init):
    if h>0 and kh>0:
        return C(f,h-1,kf_init,kh-1,kf_init,kh_init)
    else:
        return 0

