import math
def next_c(c):
	x = int(math.sqrt(c))
	i = 2
	while(i<=x):
		if((c%(i)) == 0):
			return int(c/i)
			break
		else:
			i = i+1
	if(i > x):
		return 1
def game(n):
	sum = n
	r =next_c(n)
	while(r != 1):
		sum = sum + r
		r = next_c(r)
	return sum+1
n = int(input())
print(game(n))

def nxt_num(n):
    return 10 ** len(str(n))


class CodeforcesTask373BSolution:
    def __init__(self):
        self.result = ''
        self.w_m_k = []

    def read_input(self):
        self.w_m_k = [int(x) for x in input().split(" ")]

    def process_task(self):
        k = self.w_m_k[2]
        budget = self.w_m_k[0]
        pos = self.w_m_k[1]
        length = 0
        while True:
            if (nxt_num(pos) - pos) * len(str(pos)) * k <= budget:
                budget -= (nxt_num(pos) - pos) * len(str(pos)) * k
                length += nxt_num(pos) - pos
                pos = nxt_num(pos)
            else:
                fin = budget // (len(str(pos)) * k)
                budget -= fin * (len(str(pos)) * k)
                length += fin
                break
        self.result = str(length)

    def get_result(self):
        return self.result


if __name__ == "__main__":
    Solution = CodeforcesTask373BSolution()
    Solution.read_input()
    Solution.process_task()
    print(Solution.get_result())

