def to_trenary(n):
    result = ''
    while n != 0:
        result += str(n % 3)
        n //= 3
    return ''.join(list(reversed(result)))


def from_trenary(n):
    result = 0
    c_base = 1
    n = reversed(n)
    for pos in n:
        result += c_base * int(pos)
        c_base *= 3
    return result


