def all_in(i,j,k,edges):
	my=[(i,j),(j,k),(i,k)]
	return all(x in edges for x in my)

def all_out(i,j,k,edges):
	my=[(i,j),(j,k),(i,k)]
	return all(not (x in edges) for x in my)

