def happy_guests(a, b, n, m):
	mn = min(n, m)
	a -= mn
	b -= mn
	n -= mn
	m -= mn
	if a < 0 or b < 0:
		return False
	if n > 0:
		return a+b >= n
	return min(a, b) >= m 	

def find_max_len(s):
	n = len(s)
	l, r = 0, n-1
	count = n
	while l < r and s[l] == 'a':
		l += 1
	while r > l and s[r] == 'a':
		r -= 1
	for i in range(l, r+1):
		if s[i] != 'b':
			count -= 1
	return count

def is_rectangle(a, b, c):
	for i in range(2):
		if a[i] == b[i]:
			idx = (i+1)%2
			if c[idx] >= max(a[idx], b[idx]) or c[idx] <= min(a[idx], b[idx]): 
				return True
		if b[i] == c[i]:
			idx = (i+1)%2
			if a[idx] >= max(b[idx], c[idx]) or a[idx] <= min(b[idx], c[idx]):
				return True
		if a[i] == c[i]:
			idx = (i+1)%2
			if b[idx] >= max(a[idx], c[idx]) or b[idx] <= min(a[idx], c[idx]):
				return True
	return False

