def fleq(m1, m2):
    return eq(m1, m2) or eq(m1, fliph(m2)) or eq(m1, flipv(m2))


def fliph(m):
    return [row[::-1] for row in m]


def flipv(m):
    return m[::-1]


def rot(m):
    mr = ['' for _ in range(n)]
    for i in range(n):
        x = ''
        for j in range(n):
            x = x + m[j][n-i-1]
        mr[i] = x
    return mr


