def factorials_precalc(n, mod, inverse=True):
    fact = [1]*(n+1)
    rfact = [1]*(n+1) if inverse else None
    for i in range(1, n+1):
        fact[i] = fact[i-1] * i % mod;
        if inverse:
            rfact[i] = pow(fact[i], mod - 2, mod)
    return fact, rfact
 
