def solve(n, x): 
    if n == 1:
        return 0
    if x < n:
        return pow(x, n, mod)
    sol = pow(n-1, n, mod)
    for i in range(n-1):
        sol = (sol + fact[n] * rfact[i] * rfact[n-i] * pow(n-1, i, mod) * solve(n-i, x-n+1)) % mod
    return sol
 
