def mult_mod(a, b, m):
    c = [[a[0][0] * b[0][0] + a[0][1] * b[1][0], a[0][0] * b[0][1] + a[0][1] * b[1][1]],
         [a[1][0] * b[0][0] + a[1][1] * b[1][0], a[1][0] * b[0][1] + a[1][1] * b[1][1]]]
    for i in range(2):
        for j in range(2):
            c[i][j] %= m
    return c

def pow_mod(n, m):
    p = [[1, 1],
         [1, 0]]

    a = [[1, 0],
         [0, 1]]

    while n:
        if n % 2:
            a = mult_mod(a, p, m)
        p = mult_mod(p, p, m)
        n /= 2
    return a

def fib(n, m):
