def sg(p):
    if p == 0:
        return -1
    else:
        return 1


def minim(w,h):
    if w < h:
        return (w,0)
    else:
        return (h,1)


def find_path(x, y, down, right):
    global size_n
    global size_m
    if down == 1:
        h = size_n - x
    else:
        h = x - 1
    if right == 1:
        w = size_m - y
    else:
        w = y - 1
    minimum = minim(w,h)
    p = minimum[0]
    ansX = x + p * sg(down)
    ansY = y + p * sg(right)
    if ansX == 1:
        down = 1
    if ansY == 1:
        right = 1
    if ansX == size_n:
        down = 0
    if ansY == size_m:
        right = 0
    return (ansX, ansY, down, right)


