        K.append(Ki_)
        for j, Kij in enumerate(Ki):
            for k, v in enumerate(Kij):
                for h in range(i+1):
                    Ki_[j+h][k] += v
                    Ki_[j+h][k] %= M
                Ki_[j + i + 1][i+1] += v
                Ki_[j + i + 1][i+1] %= M

    # C = comb(n, M)[n]
    C = tf(n, M)
