int_add = __pypy__.intop.int_add
int_sub = __pypy__.intop.int_sub
int_mul = __pypy__.intop.int_mul


def process(grid, a, n, m):
    aux = [[0] * 3000 for _ in range(3000)]
    for i in range(n):
        mi = deque()
        for j in range(a):
            while mi and grid[i][j] < mi[-1]:
                mi.pop()
            mi.append(grid[i][j])

        aux[0][i] = mi[0]
        for j in range(a, m):
            if mi[0] == grid[i][j - a]:
                mi.popleft()
            while mi and grid[i][j] < mi[-1]:
                mi.pop()
            mi.append(grid[i][j])
            aux[j - a + 1][i] = mi[0]

    return aux


def main():
    n, m, a, b = map(int, input().split())
    g, x, y, z = map(int, input().split())

    zinv = 1.0 / z

    def mod_mul_add(x, y, c):
        ans = int_sub(int_add(int_mul(x, y), c), int_mul(z, int(zinv * x * y + zinv * c)))
        if ans >= z:
            return ans - z
        elif ans < 0:
            return ans + z
        else:
            return ans

    grid = [[0] * 3000 for _ in range(3000)]
    for i in range(n):
        for j in range(m):
            grid[i][j] = int(g)
            g = mod_mul_add(g, x, y)

    aux1 = process(grid, b, n, m)
    aux2 = process(aux1, a, m - b + 1, n)

    ans = 0
    for i in range(n - a + 1):
        ans += sum(aux2[i][:m - b + 1])

    print(ans)


