    if x==0 or y==0:
    	return 0
    if x>y:
    	x,y=y,x
    pw = 1
    while (pw*2)<=y:
    	pw*=2
    if pw<=x:
    	return (sum(pw,pw,k,add)+sum(pw,x+y-pw-pw,k,add+pw)+solve(x-pw,y-pw,k,add))%mod
    else:
    	return (sum(pw,x,k,add)+solve(x,y-pw,k,add+pw))%mod
